/* @autogenerated */
import { InjectionToken, Type } from '@angular/core';

/** Prefijo de la URL de un adjunto guardado en local a la espera de subirlo. */
export const OFFLINE_FILE_PREFIX = 'offline-file://';

/** Tipo de operación encolada: las escrituras del provider y la subida de un adjunto. */
export type OfflineOpKind = 'add' | 'update' | 'patch' | 'delete' | 'file';

/**
 * Estado de una operación:
 * - `pending`: a la espera de subir.
 * - `failed`: el servidor la ha rechazado; hay que resolverla (reintentar, editar, descartar).
 * - `blocked`: depende de una operación fallida, así que no se intenta.
 */
export type OfflineOpStatus = 'pending' | 'failed' | 'blocked';

export interface OfflineError {
  message: string;
  /** Estado HTTP o código del backend, si lo hay. */
  status?: number;
}

/** Una escritura hecha sin conexión, guardada en IndexedDB hasta que se sube. */
export interface OfflineOp {
  /** Orden de llegada: se suben en este orden. Lo asigna IndexedDB. */
  seq?: number;
  /** Usuario y tenant que la hicieron: solo se suben con la misma sesión. */
  scope: string;
  /** Nombre del repositorio (el de sus metadatos). */
  repo: string;
  kind: OfflineOpKind;
  /** Clave de la entidad; en `file`, el id local del adjunto. */
  key: string;
  /** Datos en el formato del provider (el que recibe `add`/`update`/`patch`). */
  payload?: any;
  /** Ruta del `patch`. */
  path?: string;
  /** Valor de la entidad antes del primer cambio sin conexión: la base para resolver un conflicto. */
  base?: any;
  /** Destino y nombre del campo del adjunto (`storeFile`). */
  endpoint?: string;
  field?: string;
  fileName?: string;
  /** Texto con el que se muestra la entidad en la cola. */
  label?: string;
  status: OfflineOpStatus;
  error?: OfflineError;
  /** `seq` de la operación fallida que la bloquea. */
  blockedBy?: number;
  /**
   * Puede que el servidor ya la haya aplicado (la red falló con la petición en vuelo): un alta se comprueba antes
   * de repetirla para no duplicarla.
   */
  uncertain?: boolean;
  createdAt: number;
}

/** Estado local de una entidad con cambios pendientes; `deleted` si se ha borrado sin conexión. */
export interface OfflineShadow {
  id: string;
  scope: string;
  repo: string;
  key: string;
  value?: any;
  deleted?: boolean;
}

/** Adjunto guardado en local. */
export interface OfflineFile {
  id: string;
  scope: string;
  blob: Blob;
  name: string;
  type: string;
}

/** Última respuesta de lectura, para consultar sin conexión lo que ya se ha visto. */
export interface OfflineRead {
  id: string;
  scope: string;
  value: any;
  at: number;
}

/** Fase de la sincronización que se muestra en el diálogo. */
export type OfflineSyncState = 'idle' | 'syncing' | 'stopped' | 'offline' | 'done';

/** Estado de una operación en la sincronización en curso (solo en memoria). */
export type OfflineRunState = 'running' | 'done';

/**
 * Repositorios por nombre, cargados bajo demanda: al sincronizar, la cola instancia los de las operaciones
 * pendientes para tener su provider aunque no se hayan abierto en esta sesión.
 */
export type OfflineRepositories = Record<string, () => Promise<Type<unknown>>>;

export const OFFLINE_REPOSITORIES = new InjectionToken<OfflineRepositories>('OFFLINE_REPOSITORIES');

/** Nombre de la base de IndexedDB de la cola (para aislar las pruebas). */
export const OFFLINE_DB_NAME = new InjectionToken<string>('OFFLINE_DB_NAME');

/** Registra los repositorios que puede necesitar la cola offline (`bootstrap/repositories.config.ts`). */
export function provideOfflineRepositories(repositories: OfflineRepositories) {
  return { provide: OFFLINE_REPOSITORIES, useValue: repositories };
}

/** Estados HTTP de pasarela: el servidor no está accesible, no ha rechazado la petición. */
const UNREACHABLE = [502, 503, 504];

/**
 * El error es de conexión (no hay red o no se llega al servidor), no una respuesta del backend: `fetch` sin red
 * (Appwrite), `HttpErrorResponse` con estado 0 (REST), un timeout o un 502/503/504.
 */
export function isNetworkError(error: any): boolean {
  if (!error) {
    return false;
  }
  if (error instanceof TypeError) {
    // Chrome: «Failed to fetch»; Firefox: «NetworkError when attempting…»; Safari: «Load failed»
    return /fetch|network|load failed/i.test(error.message || '');
  }
  if (error.name === 'TimeoutError') {
    return true;
  }
  const status = error.status ?? (error.name === 'AppwriteException' ? error.code : undefined);
  if (error.name === 'HttpErrorResponse' && status === 0) {
    return true;
  }
  return UNREACHABLE.includes(status);
}

/** Error guardado de una operación rechazada. */
export function offlineError(error: any): OfflineError {
  const status = error?.status ?? error?.code;
  const message =
    error?.error?.message || error?.message || (typeof error === 'string' ? error : JSON.stringify(error ?? null));
  return typeof status === 'number' && status > 0 ? { message, status } : { message };
}
